#include <iostream>
#include <string>

int main() {
    std::string s;
    std::cin >> s;

    const std::string ans = "CODEFORCES";
    bool flag = false;

    for (int i = 0; i <= 10 && i <= static_cast<int>(s.size()); ++i) {
        if (s.size() >= 10 &&
            s.substr(0, i) + s.substr(s.size() - (10 - i)) == ans) {
            flag = true;
            break;
        }
    }

    std::cout << (flag ? "YES\n" : "NO\n");
    return 0;
}

