{
    char s[101];
    std::cin >> s;

    int len = std::strlen(s);
    int flag = 0;
    const char* ans = "CODEFORCES";

    for (int i = 0; i < len; i++)
    {
        char val[10];
        int k;

        for (int j = 0; j < i; j++)
            val[j] = s[j];

        k = i;
        for (int j = len - 10 + i; j < len; j++)
        {
            val[k] = s[j];
            k++;
        }

        for (int j = 0; j < 10; j++)
        {
            if (val[j] == ans[j])
                flag = 1;
            else
